'use strict';

// MODULES //

var promisify = require( 'node:util' ).promisify;
var crc32 = require( 'node:zlib' ).crc32;
var yauzl = require( 'yauzl' );
var limits = require( '@data-apis/limits' );
var HarvesterError = require( '@data-apis/errors/harvester-error' );


// VARIABLES //

var fromBuffer = promisify( yauzl.fromBuffer );
var decoder = new TextDecoder( 'utf-8', { 'fatal': true } );


// FUNCTIONS //

/**
* Tests whether bytes start with a recognized ZIP signature.
*
* @private
* @param {Buffer} bytes - payload
* @returns {boolean} result
*/
function isZip( bytes ) {
	return bytes.length >= 4 && bytes[ 0 ] === 0x50 && bytes[ 1 ] === 0x4b && (
		( bytes[ 2 ] === 0x03 && bytes[ 3 ] === 0x04 ) ||
		( bytes[ 2 ] === 0x05 && bytes[ 3 ] === 0x06 ) ||
		( bytes[ 2 ] === 0x07 && bytes[ 3 ] === 0x08 )
	);
}

/**
* Returns the first non-BOM, non-whitespace byte.
*
* @private
* @param {Buffer} bytes - payload
* @returns {number|undefined} byte
*/
function firstJsonByte( bytes ) {
	var offset = 0;

	if ( bytes.length >= 3 && bytes[ 0 ] === 0xef && bytes[ 1 ] === 0xbb && bytes[ 2 ] === 0xbf ) {
		offset = 3;
	}
	while ( offset < bytes.length && [0x20, 0x09, 0x0a, 0x0d].includes( bytes[ offset ] ) ) {
		offset += 1;
	}
	return bytes[ offset ];
}

/**
* Removes an optional UTF-8 byte-order mark from JSON bytes.
*
* @private
* @param {Buffer} bytes - JSON bytes
* @returns {Buffer} bytes without a BOM
*/
function stripBom( bytes ) {
	if ( bytes.length >= 3 && bytes[ 0 ] === 0xef && bytes[ 1 ] === 0xbb && bytes[ 2 ] === 0xbf ) {
		return bytes.subarray( 3 );
	}
	return bytes;
}

/**
* Validates a decoded member name.
*
* @private
* @param {string} name - member name
*/
function validateMemberName( name ) {
	if ( !name || name.includes( '\0' ) || name.includes( '\\' ) || name.startsWith( '/' ) ) {
		throw new HarvesterError( 'Unsafe ZIP member name: ' + name, {
			'code': 'UNSAFE_ZIP'
		} );
	}
	if ( name.split( '/' ).some( function isParent( part ) { return part === '..'; } ) ) {
		throw new HarvesterError( 'ZIP traversal path rejected: ' + name, {
			'code': 'UNSAFE_ZIP'
		} );
	}
}

/**
* Tests whether an explicitly typed ZIP entry is not a matching regular file or directory.
*
* @private
* @param {Object} entry - yauzl entry
* @param {string} name - decoded member name
* @returns {boolean} result
*/
function isUnsafeType( entry, name ) {
	var mode = ( entry.externalFileAttributes >>> 16 ) & 0xffff;
	var type = mode & 0xf000;

	if ( type === 0 ) {
		return false;
	}
	if ( type === 0x4000 ) {
		return !name.endsWith( '/' );
	}
	if ( type === 0x8000 ) {
		return name.endsWith( '/' );
	}
	return true;
}

/**
* Reads and CRC-validates a bounded ZIP member.
*
* @private
* @param {Object} zip - yauzl archive
* @param {Object} entry - yauzl entry
* @param {number} maxBytes - byte limit
* @returns {Promise<Buffer>} member bytes
*/
function readEntry( zip, entry, maxBytes ) {
	return new Promise( function executor( resolve, reject ) {
		zip.openReadStream( entry, function onStream( error, stream ) {
			var chunks = [];
			var total = 0;

			if ( error ) {
				reject( error );
				return;
			}
			stream.on( 'data', function onData( chunk ) {
				total += chunk.length;
				if ( total > maxBytes ) {
					stream.destroy( new HarvesterError( 'ZIP member exceeded ' + maxBytes + ' bytes', {
						'code': 'ZIP_BOMB'
					} ) );
					return;
				}
				chunks.push( chunk );
			} );
			stream.once( 'error', reject );
			stream.once( 'end', function onEnd() {
				var bytes = Buffer.concat( chunks, total );

				if ( crc32( bytes ) !== entry.crc32 ) {
					reject( new HarvesterError( 'ZIP member CRC mismatch', {
						'code': 'INVALID_ZIP_CRC'
					} ) );
					return;
				}
				resolve( bytes );
			} );
		} );
	} );
}

/**
* Decodes selected reports from a ZIP payload.
*
* @private
* @param {Buffer} bytes - archive bytes
* @param {Object} options - decoding options
* @returns {Promise<Array>} report candidates
*/
async function decodeZip( bytes, options ) {
	var zip = await fromBuffer( bytes, {
		'lazyEntries': true,
		'decodeStrings': false,
		'validateEntrySizes': true,
		'strictFileNames': true
	} );
	var entries = [];
	var names = new Set();
	var entryCount = 0;
	var expandedBytes = 0;

	try {
		await new Promise( function executor( resolve, reject ) {
			zip.once( 'error', reject );
			zip.once( 'end', resolve );
			zip.on( 'entry', function onEntry( entry ) {
				Promise.resolve().then( async function processEntry() {
					var name;
					var selected;
					var entryBytes;

					entryCount += 1;
					if ( entryCount > ( options.maxEntries || limits.maxZipEntries ) ) {
						throw new HarvesterError( 'ZIP contains too many entries', { 'code': 'ZIP_BOMB' } );
					}
					try {
						name = decoder.decode( entry.fileName );
					} catch ( error ) {
						throw new HarvesterError( 'ZIP member name is not valid UTF-8', {
							'code': 'INVALID_ZIP_NAME',
							'cause': error
						} );
					}
					validateMemberName( name );
					if ( names.has( name ) ) {
						throw new HarvesterError( 'Duplicate ZIP member: ' + name, { 'code': 'UNSAFE_ZIP' } );
					}
					names.add( name );
					if ( ( entry.generalPurposeBitFlag & 0x1 ) !== 0 || isUnsafeType( entry, name ) ) {
						throw new HarvesterError( 'Unsafe ZIP member rejected: ' + name, { 'code': 'UNSAFE_ZIP' } );
					}
					if ( name.endsWith( '/' ) ) {
						zip.readEntry();
						return;
					}
					selected = options.file ? name === options.file : name.endsWith( '.json' );
					if ( !selected && !options.file ) {
						throw new HarvesterError( 'Unexpected non-JSON ZIP member: ' + name, {
							'code': 'UNEXPECTED_ZIP_MEMBER'
						} );
					}
					if ( selected ) {
						if ( entry.uncompressedSize > ( options.maxJsonBytes || limits.maxJsonBytes ) ) {
							throw new HarvesterError( 'ZIP member is too large: ' + name, { 'code': 'ZIP_BOMB' } );
						}
						expandedBytes += entry.uncompressedSize;
						if ( expandedBytes > ( options.maxExpandedBytes || limits.maxZipExpandedBytes ) ) {
							throw new HarvesterError( 'ZIP aggregate expansion limit exceeded', { 'code': 'ZIP_BOMB' } );
						}
						entryBytes = await readEntry( zip, entry, options.maxJsonBytes || limits.maxJsonBytes );
						decoder.decode( entryBytes );
						entries.push( { 'member': name, 'bytes': stripBom( entryBytes ) } );
					}
					zip.readEntry();
				} ).catch( reject );
			} );
			zip.readEntry();
		} );
	} finally {
		zip.close();
	}
	if ( options.file && !names.has( options.file ) ) {
		throw new HarvesterError( 'Selected ZIP member was not found: ' + options.file, {
			'code': 'MISSING_ZIP_MEMBER'
		} );
	}
	if ( entries.length === 0 ) {
		throw new HarvesterError( 'ZIP did not contain a selected JSON report', { 'code': 'EMPTY_ZIP' } );
	}
	return entries;
}


// MAIN //

/**
* Detects and decodes a direct JSON or ZIP payload.
*
* @param {Buffer|Uint8Array} bytes - payload bytes
* @param {Object} [options] - decoder options
* @returns {Promise<Object>} format and report candidates
*/
async function decodePayload( bytes, options ) {
	var first;

	options = options || {};
	if ( !Buffer.isBuffer( bytes ) ) {
		bytes = Buffer.from( bytes );
	}
	if ( bytes.length === 0 ) {
		throw new HarvesterError( 'Downloaded payload is empty', { 'code': 'EMPTY_PAYLOAD' } );
	}
	first = firstJsonByte( bytes );
	if ( first === 0x7b || first === 0x5b ) {
		if ( bytes.length > ( options.maxJsonBytes || limits.maxJsonBytes ) ) {
			throw new HarvesterError( 'JSON payload is too large', { 'code': 'RESPONSE_TOO_LARGE' } );
		}
		decoder.decode( bytes );
		return {
			'format': 'json',
			'candidates': [{ 'bytes': stripBom( bytes ) }]
		};
	}
	if ( isZip( bytes ) ) {
		return {
			'format': 'zip',
			'candidates': await decodeZip( bytes, options )
		};
	}
	throw new HarvesterError( 'Downloaded payload is neither JSON nor ZIP', {
		'code': 'UNKNOWN_PAYLOAD'
	} );
}


// EXPORTS //

module.exports = decodePayload;
